// El nodo Execute Command devuelve la salida cruda en `stdout`.
// La parseamos y armamos el mensaje que se va a enviar.

const salida = $input.first().json.stdout;

let reporte;
try {
  reporte = JSON.parse(salida);
} catch (e) {
  throw new Error('El script no devolvio JSON valido. Salida: ' + String(salida).slice(0, 500));
}

const top = (reporte.detalle || []).slice(0, 5);

const lineas = top.map(p => {
  const flecha = p.desvio_pct < 0 ? '🔻' : '🔺';
  return `${flecha} *${p.sigla}* (${p.empresa})\n` +
         `   ${p.caudal_real_bbld} bbl/d vs ${p.caudal_esperado_bbld} esperados (${p.desvio_pct > 0 ? '+' : ''}${p.desvio_pct}%)`;
});

const mensaje =
  `📊 *Monitor Vaca Muerta*\n\n` +
  `Pozos evaluados: ${reporte.pozos_evaluados}\n` +
  `Desvios detectados: *${reporte.anomalias_encontradas}*\n` +
  `   🔻 ${reporte.bajo_rendimiento} por debajo de su curva\n` +
  `   🔺 ${reporte.sobre_rendimiento} por encima\n\n` +
  (lineas.length ? `*Mayores desvios:*\n${lineas.join('\n')}\n\n` : '') +
  `_Umbral: ±${reporte.umbral_pct}%. Un desvio no es un diagnostico: es una senal para mirar el pozo._`;

return [{ json: { mensaje, anomalias: reporte.anomalias_encontradas, reporte } }];
